pous.declaration:
FUNCTION_BLOCK HVAC
VAR_INPUT
    OCCUPANCY_DETECTED : BOOL;
    ENERGY_SAVING_MODE : BOOL;
    HVAC_MODE_SELECTOR : INT;
END_VAR
VAR_OUTPUT
    SUPPLY_FAN_RUN : BOOL;
    TEMP_SETPOINT_ADJUST : INT;
END_VAR
VAR
    fanTon : TON;
    adjust : INT;
END_VAR

pous.implementation:
fanTon(IN := OCCUPANCY_DETECTED AND (HVAC_MODE_SELECTOR <> 3), PT := T#30s);
SUPPLY_FAN_RUN := fanTon.Q;
adjust := 0;
CASE HVAC_MODE_SELECTOR OF
0:
    IF OCCUPANCY_DETECTED THEN
        adjust := 0;
    ELSIF ENERGY_SAVING_MODE THEN
        adjust := 3;
    ELSE
        adjust := 2;
    END_IF
1:
    IF OCCUPANCY_DETECTED THEN
        adjust := 0;
    ELSE
        adjust := 1;
    END_IF
2:
    IF OCCUPANCY_DETECTED THEN
        adjust := 0;
    ELSE
        adjust := 4;
    END_IF
3:
    adjust := 4;
END_CASE
IF adjust > 4 THEN
    adjust := 4;
END_IF
IF adjust < -4 THEN
    adjust := -4;
END_IF
TEMP_SETPOINT_ADJUST := adjust;
